export const KEY='dira-practice-v1';
export function newAttempt(){return {id:crypto.randomUUID(),startedAt:new Date().toISOString(),drafts:{},versions:[],reviews:[],revealed:false,complete:false};}
export function initial(){const a=newAttempt();return {schema:1,caseId:'peru-001',current:a.id,attempts:[a]};}
export function validate(s){if(!s||s.schema!==1||s.caseId!=='peru-001'||!Array.isArray(s.attempts)||!s.attempts.length||s.attempts.length>1000)throw Error('This is not a supported Dira backup.');const ids=new Set();for(const a of s.attempts){if(!a||typeof a.id!=='string'||ids.has(a.id)||!Number.isFinite(Date.parse(a.startedAt))||typeof a.complete!=='boolean'||typeof a.revealed!=='boolean'||!a.drafts||Array.isArray(a.drafts)||typeof a.drafts!=='object'||!Array.isArray(a.versions)||!Array.isArray(a.reviews))throw Error('Invalid attempt data.');ids.add(a.id);for(const [k,d]of Object.entries(a.drafts)){if(!['0','1','2','3'].includes(k)||!d||typeof d.text!=='string'||typeof d.follow!=='string'||!['Independent','After tutoring'].includes(d.assistance)||!Array.isArray(d.table)||d.table.length!==3||d.table.some(r=>!Array.isArray(r)||r.length!==3||r.some(v=>typeof v!=='string')))throw Error('Invalid draft.');}for(const v of a.versions){if(!v||typeof v.id!=='string'||!Number.isInteger(v.stage)||v.stage<0||v.stage>3||!Number.isFinite(Date.parse(v.date))||!v.draft)throw Error('Invalid saved version.');validateDraft(v.draft);}for(const r of a.reviews){if(!r||typeof r.id!=='string'||typeof r.text!=='string'||!Number.isFinite(Date.parse(r.date)))throw Error('Invalid review.');}}if(!ids.has(s.current))throw Error('Current attempt is missing.');return s;}
function validateDraft(d){validate({schema:1,caseId:'peru-001',current:'check',attempts:[{id:'check',startedAt:'2026-01-01',complete:false,revealed:false,drafts:{0:d},versions:[],reviews:[]}]});}
export function blankDraft(){return {text:'',follow:'',assistance:'Independent',table:Array.from({length:3},()=>['','',''])};}
export function mergeBackups(current,incoming){validate(incoming);const out=structuredClone(current);for(const a of incoming.attempts){const exists=out.attempts.find(x=>x.id===a.id);if(!exists){out.attempts.push(a);continue;}for(const key of ['versions','reviews'])for(const item of a[key])if(!exists[key].some(v=>v.id===item.id))exists[key].push(item);/* Current drafts stay intact; imported saved versions remain accessible. */}return validate(out);}
